def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    if sys.platform == "win32":
        cmd = list(cmd)
        if cmd[0].endswith('.py') and os.path.isfile(cmd[0]):
            interpreter = os.path.normpath(sys.executable)
            shebang_interpreter = _get_shebang_interpreter(cmd[0])
            if shebang_interpreter:
                cmd[0] = shebang_interpreter + ' "' + cmd[0] + '"'
            else:
                cmd[0] = '"' + cmd[0] + '"'
            return tuple([interpreter] + cmd)
        else:
            return tuple(cmd)
    return tuple(cmd)

def _get_shebang_interpreter(script_path):
    import codecs

    with codecs.open(script_path, 'r', encoding='utf-8') as file:
        first_line = file.readline().strip()
        if first_line.startswith('#!'):
            interpreter = first_line[2:].strip()
            if interpreter:
                return interpreter
    return None

