def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    from collections import OrderedDict

    merged_ordering = []
    order_map = OrderedDict()

    for ordering in orderings:
        for index, item in enumerate(ordering):
            if item not in order_map:
                order_map[item] = []
            order_map[item].extend(ordering[index+1:])

    def add_to_merged(item):
        if item not in merged_ordering:
            merged_ordering.append(item)
            if item in order_map:
                for next_item in order_map[item]:
                    add_to_merged(next_item)

    # Start with the first item of each ordering
    for ordering in orderings:
        if ordering:
            add_to_merged(ordering[0])

    return merged_ordering

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal_list = []
    for cls in classes:
        if cls not in seen:
            minimal_list.append(cls)
            seen.add(cls)
            seen.update(set(cls.__mro__[1:]))
    return minimal_list

