def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
    """
    if isinstance(params, dict):
        out_params = {key: params[key] for key in sorted(params.keys())}
        formatted_sql = sql
        for key in params:
            placeholder = f"%({key})s"
            if self.SQLParams.in_style == "pyformat":
                formatted_sql = formatted_sql.replace(placeholder, ":" + key)
            elif self.SQLParams.in_style == "format":
                formatted_sql = formatted_sql.replace(placeholder, "%s")
            elif self.SQLParams.in_style == "numeric":
                formatted_sql = formatted_sql.replace(placeholder, f":{list(params.keys()).index(key) + 1}")
    else:
        out_params = list(params)
        if self.SQLParams.in_style == "qmark":
            formatted_sql = sql.replace("?", "%s")
        elif self.SQLParams.in_style == "format":
            formatted_sql = sql.replace("%s", "?")
        elif self.SQLParams.in_style == "numeric":
            formatted_sql = re.sub(r"%\((\d+)\)s", lambda m: "$" + m.group(1), sql)
        else:
            formatted_sql = sql

    return formatted_sql, out_params

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of
		the in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
		*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
		"""
		if isinstance(params, dict):
			# Assuming named parameters
			if self.SQLParams.out_style == 'named':
				return sql, params
			elif self.SQLParams.out_style == 'qmark':
				out_params = []
				for key in sorted(params.keys()):
					sql = sql.replace(f':{key}', '?')
					out_params.append(params[key])
				return sql, out_params
			elif self.SQLParams.out_style == 'numeric':
				out_params = []
				for i, key in enumerate(sorted(params.keys())):
					sql = sql.replace(f':{key}', f':{i+1}')
					out_params.append(params[key])
				return sql, out_params
			elif self.SQLParams.out_style == 'pyformat':
				out_params = {}
				for key in params:
					new_key = f':{key}'
					sql = sql.replace(f':{key}', new_key)
					out_params[new_key] = params[key]
				return sql, out_params
		else:
			# Assuming positional parameters
			if self.SQLParams.out_style == 'qmark':
				return sql, params
			elif self.SQLParams.out_style == 'numeric':
				out_params = {i+1: val for i, val in enumerate(params)}
				sql = sql.replace('?', ':{}'.format(i+1))
				return sql, out_params
			elif self.SQLParams.out_style == 'named':
				out_params = {f':p{i+1}': val for i, val in enumerate(params)}
				for i, val in enumerate(params):
					sql = sql.replace('?', f':p{i+1}')
				return sql, out_params
			elif self.SQLParams.out_style == 'pyformat':
				out_params = {f'p{i+1}': val for i, val in enumerate(params)}
				for i, val in enumerate(params):
					sql = sql.replace('?', f'%(p{i+1})s')
				return sql, out_params

		return sql, params  # Fallback, return as is if no conversion is applicable

