        elif isinstance(params, Sequence):
            for j, value in enumerate(params):
                placeholder = '$' + str(j + 1) if self.SQLParams.in_style == 'numeric' else '?'
                new_sql = new_sql.replace(placeholder, out_style_marker + str(j))
        else:
            raise ValueError("Params must be a Mapping or Sequence")

        new_sql_parts.append(new_sql)
        param_sets.append(params)

    if self.SQLParams.in_style in ['qmark', 'numeric', 'format']:
        final_sql = new_sql_parts[0]  # all should be the same
    else:
        final_sql = sql  # placeholder names are not replaced in the original sql string for these styles

    return final_sql, param_sets

