def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior must be an instance of InventoryValidator")

    if self.inventory.keys() != prior.inventory.keys():
        raise ValueError("The prior inventory must have the same items as the current inventory")

    for item, current_value in self.inventory.items():
        prior_value = prior.inventory[item]
        if not isinstance(prior_value, (int, float)) or prior_value < 0:
            raise ValueError(f"The prior value for {item} must be a non-negative number")
        if current_value < prior_value:
            raise ValueError(f"The current value for {item} cannot be less than the prior value")

    return True

