def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    representation = indent_str + "Representation of self:\n"
    for attr, value in self.__dict__.items():
        if debug or not attr.startswith('_'):
            representation += indent_str + f"  {attr}: {value}\n"
    return representation

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    repr_str = f"{indent_str}<{self.__class__.__name__}>\n"
    for key, value in self.__dict__.items():
        if hasattr(value, 'pretty'):
            repr_str += f"{indent_str}  {key}: {value.pretty(indent + 2, debug)}\n"
        else:
            repr_str += f"{indent_str}  {key}: {repr(value)}\n"
    return repr_str

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = []
    parts.append(f"{indent_str}Instance of {self.__class__.__name__}:\n")
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple, set)):
            parts.append(f"{indent_str}  {key}: [\n")
            for item in value:
                parts.append(f"{indent_str}    {item},\n")
            parts.append(f"{indent_str}  ],\n")
        elif isinstance(value, dict):
            parts.append(f"{indent_str}  {key}: {{\n")
            for sub_key, sub_value in value.items():
                parts.append(f"{indent_str}    {sub_key}: {sub_value},\n")
            parts.append(f"{indent_str}  }},\n")
        else:
            parts.append(f"{indent_str}  {key}: {value}\n")
    return ''.join(parts)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        if isinstance(expr, tuple):
            op, a, b = expr
            if op == '&':
                if b == (('|', a, '_') or ('|', '_', a)):
                    new_args.append(a)
                elif b == (('&', ('~', a), '_') or ('&', '_', ('~', a))):
                    new_args.append(('&', a, b[2]))
                else:
                    new_args.append(expr)
            elif op == '|':
                if b == (('&', a, '_') or ('&', '_', a)):
                    new_args.append(a)
                elif b == (('|', ('~', a), '_') or ('|', '_', ('~', a))):
                    new_args.append(('|', a, b[2]))
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if sys.version_info[0] >= 3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

