def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string")

    import re
    match = re.match(r"^\s*(\d+)\s*([a-zA-Z]+)\s*$", frequency)
    if not match:
        raise ValueError("Invalid frequency format")

    quantity, unit = match.groups()
    quantity = int(quantity)

    if unit in ["second", "seconds"]:
        return datetime.timedelta(seconds=quantity)
    elif unit in ["minute", "minutes"]:
        return datetime.timedelta(minutes=quantity)
    elif unit in ["hour", "hours"]:
        return datetime.timedelta(hours=quantity)
    elif unit in ["day", "days"]:
        return datetime.timedelta(days=quantity)
    elif unit in ["week", "weeks"]:
        return datetime.timedelta(weeks=quantity)
    elif unit in ["month", "months"]:
        raise ValueError("Months cannot be directly converted to a timedelta")
    elif unit in ["year", "years"]:
        raise ValueError("Years cannot be directly converted to a timedelta")
    else:
        raise ValueError("Unknown time unit: {}".format(unit))

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        return host in ('localhost', '127.0.0.1', '::1') or socket.gethostbyname(host) == '127.0.0.1'
    except socket.gaierror:
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Get the list of addresses for the host
        addr_info = socket.getaddrinfo(host, None)
        # Check if any of the addresses is a loopback address
        for addr in addr_info:
            if addr[4][0].startswith('127.') or addr[4][0] == '::1':
                return True
    except socket.gaierror:
        pass
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        resolved = socket.gethostbyname(host)
        return resolved in ('::1', '127.0.0.1')
    except socket.error:
        return False

