def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    command = command + args
    if verbose:
        print("Running command:", command)
    try:
        with open(os.devnull, 'w') as devnull:
            stderr = devnull if hide_stderr else None
            output = subprocess.check_output(
                command, cwd=cwd, stderr=stderr, env=env
            )
            if verbose:
                print("Output:", output.decode())
            return output
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code:", e.returncode)
        if not hide_stderr:
            print("Error output:", e.output.decode())
        raise

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        command = [commands] + args
        stderr_redirection = subprocess.DEVNULL if hide_stderr else subprocess.STDOUT
        process = subprocess.run(command, cwd=cwd, env=env, capture_output=True, stderr=stderr_redirection, text=True)
        if verbose:
            print(process.stdout)
            if process.stderr and not hide_stderr:
                print(process.stderr, file=sys.stderr)
        if process.returncode != 0:
            raise subprocess.CalledProcessError(returncode=process.returncode, cmd=command, output=process.stdout, stderr=process.stderr)
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(returncode=e.returncode, cmd=e.cmd, output=e.output, stderr=e.stderr) from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        raise ValueError("commands must be a list of command strings.")

    if not isinstance(args, list):
        raise ValueError("args must be a list of arguments.")

    full_command = commands + args
    process = subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT)

    stdout, stderr = process.communicate()

    if verbose:
        print(stdout.decode())

    if process.returncode != 0:
        raise subprocess.CalledProcessError(returncode=process.returncode, cmd=full_command, output=stdout, stderr=stderr)

