def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import toml

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                raw_config = file.read()
                config = toml.loads(raw_config)
                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
                if overrides:
                    config.update(overrides)
                config_dict[filename] = config
        except (FileNotFoundError, toml.TomlDecodeError) as e:
            log_record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(log_record)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import logging.config
    import os
    import toml
    import yaml

    configs = {}
    log_records = []

    def parse_config(filename):
        _, ext = os.path.splitext(filename)
        if ext.lower() == '.toml':
            with open(filename) as fd:
                return toml.load(fd)
        elif ext.lower() in ('.yaml', '.yml'):
            with open(filename) as fd:
                return yaml.safe_load(fd)
        else:
            raise ValueError(f"Unsupported configuration file extension: {ext}")

    for filename in config_filenames:
        try:
            config = parse_config(filename)
            if overrides:
                config.update(overrides)
            configs[filename] = config
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(record)

    return configs, log_records

