def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import toml
    import json

    if overrides is None:
        overrides = {}

    configurations = {}
    errors = []

    def load_and_parse(filename):
        if not os.path.exists(filename):
            errors.append(logging.LogRecord('config_loader', logging.ERROR, filename, 0, f"File not found: {filename}", (), None))
            return None

        _, ext = os.path.splitext(filename)
        try:
            with open(filename) as f:
                if ext == '.toml':
                    config = toml.load(f)
                elif ext in ('.json', '.js'):
                    config = json.load(f)
                else:
                    errors.append(logging.LogRecord('config_loader', logging.ERROR, filename, 0, f"Unsupported file type: {filename}", (), None))
                    return None
        except Exception as e:
            errors.append(logging.LogRecord('config_loader', logging.ERROR, filename, 0, f"Error parsing {filename}: {e}", (), None))
            return None

        return config

    for filename in config_filenames:
        config = load_and_parse(filename)
        if config is not None:
            configurations[filename] = config

    for key, value in overrides.items():
        for config in configurations.values():
            config[key] = value

    return configurations, errors

