def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    else:
        return list(seq), type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq))
    else:
        try:
            # Attempt to convert to a list if possible
            sequence = list(seq)
            return (sequence, type(sequence))
        except TypeError:
            # If seq is not iterable, treat it as a single-element sequence
            return ([seq], list)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
